root = pathlib.Path(__file__).parent
for name, (color, paths) in ICONS.items():
    body = "".join(f'<path d="{d}"/>' for d in paths)
    svg = f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" width="16" height="16" fill="{color}">{body}</svg>\n'
    (root / "svg" / f"{name}.svg").write_text(svg)
    cairosvg.svg2png(bytestring=svg.encode(), write_to=str(root / f"{name}.png"), output_width=SIZE, output_height=SIZE)
